static char*suffix(const char*p,const char*s){size_t a=strlen(p),b=strlen(s);char*q=(char*)malloc(a+b+1);if(q){memcpy(q,p,a);memcpy(q+a,s,b+1);}return q;}
static uint64_t rng(uint64_t*x){*x^=*x>>12;*x^=*x<<25;*x^=*x>>27;return *x*UINT64_C(2685821657736338717);}
static int parse_size(const char*s,size_t*out){if(!s||!*s)return 0;size_t n=0;for(const unsigned char*p=(const unsigned char*)s;*p;p++){if(*p<'0'||*p>'9')return 0;unsigned d=*p-'0';if(n>(SIZE_MAX-d)/10)return 0;n=n*10+d;}if(!n)return 0;*out=n;return 1;}
static int add_position_features(float*out,size_t width,double x,double y){if(!out||width<4||!isfinite(x)||!isfinite(y))return 0;memset(out,0,width*sizeof(float));size_t axis_width=width/2;for(size_t axis=0;axis<2;axis++){size_t base=axis*axis_width,slots=axis?width-base:axis_width,pairs=slots/2;double position=axis?y:x;for(size_t i=0;i<pairs;i++){double cycles=pairs==1?1.0:0.5+3.5*(double)i/(double)(pairs-1),phase=6.2831853071795864769*cycles*position;out[base+2*i]=(float)sin(phase);out[base+2*i+1]=(float)cos(phase);}}return 1;}
static uint32_t global_token(size_t view,size_t codes,size_t contexts){return (uint32_t)(256+codes+contexts+view);}
static uint32_t coord_token(size_t axis,size_t value,size_t codes){return (uint32_t)(256+codes+(axis?8:0)+value);}
static size_t normalized_coord(size_t position,size_t extent){return extent<2?0:(size_t)llround(7.0*(double)position/(double)(extent-1));}
static uint32_t sample_code(const float*logits,uint32_t base,uint32_t count,double temperature,uint64_t*state){float maximum=logits[base];for(uint32_t c=1;c<count;c++)if(logits[base+c]>maximum)maximum=logits[base+c];double total=0;for(uint32_t c=0;c<count;c++)total+=exp(((double)logits[base+c]-maximum)/temperature);double draw=(double)(rng(state)>>11)*(1.0/9007199254740992.0)*total;uint32_t selected=count-1;for(uint32_t c=0;c<count;c++){draw-=exp(((double)logits[base+c]-maximum)/temperature);if(draw<=0){selected=c;break;}}return selected+1;}
static void code_distribution(const float*logits,uint32_t base,uint32_t count,double*entropy,double*top1){float maximum=logits[base];for(uint32_t c=1;c<count;c++)if(logits[base+c]>maximum)maximum=logits[base+c];double total=0.0;for(uint32_t c=0;c<count;c++)total+=exp((double)logits[base+c]-maximum);double h=0.0,best=0.0;for(uint32_t c=0;c<count;c++){double p=exp((double)logits[base+c]-maximum)/total;if(p>0.0)h-=p*log(p);if(p>best)best=p;}*entropy+=h;*top1+=best;}
static void print_code_metrics(const uint32_t*codes,size_t count,size_t levels,uint32_t code_count,const AMA10Image*im,size_t grid_w,size_t grid_h,size_t stride_x,size_t stride_y){
 uint32_t frequencies[256]={0};size_t unique=0,repeats=0;uint32_t maximum=0;double entropy=0.0;
 for(size_t i=0;i<count;i++){uint32_t code=codes[i*levels];if(!frequencies[code-1])unique++;frequencies[code-1]++;if(i&&code==codes[(i-1)*levels])repeats++;if(frequencies[code-1]>maximum)maximum=frequencies[code-1];}
 for(uint32_t i=0;i<code_count;i++)if(frequencies[i]){double p=(double)frequencies[i]/(double)count;entropy-=p*log(p);}
 double boundary_sum=0.0;uint64_t boundary_values=0;
 for(size_t x=stride_x;x<im->width&&x<grid_w*stride_x;x+=stride_x){for(size_t y=0;y<im->height;y++)for(size_t c=0;c<3;c++){size_t a=(y*im->width+x-1)*3+c,b=(y*im->width+x)*3+c;boundary_sum+=fabs((double)im->rgb[a]-(double)im->rgb[b]);boundary_values++;}}
 for(size_t y=stride_y;y<im->height&&y<grid_h*stride_y;y+=stride_y){for(size_t x=0;x<im->width;x++)for(size_t c=0;c<3;c++){size_t a=((y-1)*im->width+x)*3+c,b=(y*im->width+x)*3+c;boundary_sum+=fabs((double)im->rgb[a]-(double)im->rgb[b]);boundary_values++;}}
 printf("tile_code_unique=%zu/%u code_entropy_nats=%.4f max_code_share=%.4f adjacent_code_repeat=%.4f mean_grid_boundary_rgb_jump=%.3f residual_levels=%zu\n",unique,code_count,entropy,(double)maximum/(double)count,count>1?(double)repeats/(double)(count-1):0.0,boundary_values?boundary_sum/(double)boundary_values:0.0,levels);
}
static int parse_seed(const char*s,uint64_t*out){if(!s||!*s)return 0;uint64_t n=0;for(const unsigned char*p=(const unsigned char*)s;*p;p++){if(*p<'0'||*p>'9')return 0;unsigned d=*p-'0';if(n>(UINT64_MAX-d)/10)return 0;n=n*10+d;}*out=n;return 1;}
int main(int argc,char**argv){if(argc<4||argc>9){fprintf(stderr,"usage: %s <checkpoint.ama> <prompt.txt> <output.ppm> [language=en] [temperature=0.8] [width=64] [height=64] [seed=1]\n",argv[0]);return 2;}
 const char*lang=argc>=5?argv[4]:"en";double temp=0.8;size_t width=64,height=64;uint64_t random_seed=1;if(argc>=6){char*end=NULL;temp=strtod(argv[5],&end);if(end==argv[5]||*end||!isfinite(temp)||temp<0.05||temp>5.0)return 2;}if(argc>=7&&!parse_size(argv[6],&width))return 2;if(argc>=8&&!parse_size(argv[7],&height))return 2;if(argc>=9&&!parse_seed(argv[8],&random_seed))return 2;if(strlen(lang)>8)return 2;FILE*f=fopen(argv[2],"rb");if(!f)return 1;if(fseek(f,0,SEEK_END)){fclose(f);return 1;}long z=ftell(f);if(z<1||z>4096||fseek(f,0,SEEK_SET)){fclose(f);return 1;}unsigned char*text=(unsigned char*)malloc((size_t)z+1);if(!text){fclose(f);return 1;}int good=fread(text,1,(size_t)z,f)==(size_t)z&&fclose(f)==0;if(!good){free(text);return 1;}while(z>0&&(text[z-1]=='\n'||text[z-1]=='\r'))z--;if(!z){free(text);return 1;}
 AMA10Model m={0};AMA10Tokenizer tok={0};AMA10Optimizer opt={0};AMA10State st={0};AMA10CheckpointProgress pr={0};AMA10ImageCodebook book={0};uint32_t*ids=NULL,*codes=NULL,*context_codes=NULL,*layout_codes=NULL;size_t ni=0,ncodes=0,nlayout=0;float*logits=NULL,*position=NULL;AMA10Image im={0};char*vp=suffix(argv[1],".vq");int hierarchical=0,fourier=0,coordinate=0,context_book=0;int ok=vp&&ama10_checkpoint_load(argv[1],&m,&tok,&opt,&st,&pr)&&ama10_image_codebook_load(&book,vp)&&book.code_count<255&&m.vocabulary==tok.vocabulary_size&&m.input_width>=4;if(ok){context_book=book.context_code_count>0;hierarchical=context_book?tok.vocabulary_size==263+book.code_count+book.context_code_count:tok.vocabulary_size==263+book.code_count;fourier=!context_book&&tok.vocabulary_size==257+book.code_count;coordinate=!context_book&&tok.vocabulary_size==273+book.code_count;ok=hierarchical||fourier||coordinate;}free(vp);if(!ok)goto done;
 char prefix[32];int pn=snprintf(prefix,sizeof(prefix),"<lang:%s> ",lang);size_t total=(size_t)pn+(size_t)z+2;unsigned char*b=(unsigned char*)malloc(total);if(!b)goto done;memcpy(b,prefix,(size_t)pn);memcpy(b+pn,text,(size_t)z);b[pn+z]='\n';b[pn+z+1]=0;ok=ama10_tokenizer_encode(&tok,b,total,&ids,&ni);free(b);if(!ok)goto done;
 size_t dx=width>book.patch_width?width-book.patch_width:0,dy=height>book.patch_height?height-book.patch_height:0;size_t grid_w=dx/book.stride_width+(dx%book.stride_width!=0)+1,grid_h=dy/book.stride_height+(dy%book.stride_height!=0)+1;if(grid_w>SIZE_MAX/grid_h)goto done;ncodes=grid_w*grid_h;if(!ncodes||ncodes>SIZE_MAX/book.levels||ncodes*book.levels>SIZE_MAX/sizeof(*codes))goto done;size_t layout_w=grid_w/4+(grid_w%4!=0),layout_h=grid_h/4+(grid_h%4!=0);if(layout_w>SIZE_MAX/layout_h)goto done;nlayout=layout_w*layout_h;codes=(uint32_t*)malloc(ncodes*book.levels*sizeof(*codes));layout_codes=hierarchical?(uint32_t*)malloc(nlayout*sizeof(*layout_codes)):NULL;logits=(float*)malloc(m.vocabulary*sizeof(float));if(fourier||hierarchical)position=(float*)malloc(m.input_width*sizeof(float));if(hierarchical)context_codes=(uint32_t*)malloc(5*sizeof(*context_codes));if(!logits||((fourier||hierarchical)&&!position)||(hierarchical&&(!context_codes||!layout_codes))||!codes)goto done;unsigned default_depth=pr.depth?pr.depth:2;size_t prefix_depth=default_depth;if(prefix_depth>UINT_MAX)goto done;ama10_state_reset(&st);for(size_t i=0;i<ni;i++)if(!ama10_step(&m,&st,ids[i],logits,(unsigned)prefix_depth,2.0f)){ok=0;goto done;}
 uint64_t random_state=random_seed;if(!random_state)random_state=UINT64_C(0x9e3779b97f4a7c15);double image_entropy_sum=0.0,image_top1_sum=0.0;size_t image_prediction_count=0;
 if(hierarchical){
   for(size_t v=0;v<5;v++){if(!ama10_step(&m,&st,global_token(v,book.code_count,context_book?book.context_code_count:0),logits,(unsigned)prefix_depth,2.0f)){ok=0;goto done;}uint32_t context_base=context_book?256+book.code_count:256,context_count=context_book?book.context_code_count:book.code_count;context_codes[v]=sample_code(logits,context_base,context_count,temp,&random_state);if(!ama10_step(&m,&st,context_base+context_codes[v]-1,logits,(unsigned)prefix_depth,2.0f)){ok=0;goto done;}}
  if(!ama10_step(&m,&st,global_token(5,book.code_count,book.context_code_count),logits,(unsigned)prefix_depth,2.0f)){ok=0;goto done;}
  for(size_t k=0;k<nlayout;k++){size_t x=k%layout_w,y=k/layout_w;double lx=layout_w<2?0.5:(double)x/(double)(layout_w-1),ly=layout_h<2?0.5:(double)y/(double)(layout_h-1);if(!add_position_features(position,m.input_width,lx,ly)||!ama10_step_features(&m,&st,position,logits,(unsigned)prefix_depth,2.0f)){ok=0;goto done;}layout_codes[k]=sample_code(logits,256,book.code_count,temp,&random_state);if(!ama10_step(&m,&st,256+layout_codes[k]-1,logits,(unsigned)prefix_depth,2.0f)){ok=0;goto done;}}
  printf("global_context_codes=%u,%u,%u,%u,%u context_codebook=%u coarse_layout=%zux%zu\n",context_codes[0],context_codes[1],context_codes[2],context_codes[3],context_codes[4],context_book?book.context_code_count:book.code_count,layout_w,layout_h);
  for(size_t p=0;p<ncodes;p++){
    unsigned recurrent_depth=(unsigned)prefix_depth;
   size_t px=p%grid_w,py=p/grid_w;
   double nx=grid_w<2?0.5:(double)px/(double)(grid_w-1),ny=grid_h<2?0.5:(double)py/(double)(grid_h-1);
    if(!add_position_features(position,m.input_width,nx,ny)||!ama10_step_features(&m,&st,position,logits,recurrent_depth,2.0f)){ok=0;goto done;}
   code_distribution(logits,256,book.code_count,&image_entropy_sum,&image_top1_sum);image_prediction_count++;codes[p*book.levels]=sample_code(logits,256,book.code_count,temp,&random_state);
   if(!ama10_step(&m,&st,256+codes[p*book.levels]-1,logits,recurrent_depth,2.0f)){ok=0;goto done;}
   if(book.levels==2){code_distribution(logits,256,book.code_count,&image_entropy_sum,&image_top1_sum);image_prediction_count++;codes[p*book.levels+1]=sample_code(logits,256,book.code_count,temp,&random_state);if(!ama10_step(&m,&st,256+codes[p*book.levels+1]-1,logits,recurrent_depth,2.0f)){ok=0;goto done;}}
  }
 }else if(fourier){
  for(size_t p=0;p<ncodes;p++){size_t px=p%grid_w,py=p/grid_w;double nx=grid_w<2?0.5:(double)px/(double)(grid_w-1),ny=grid_h<2?0.5:(double)py/(double)(grid_h-1);if(!add_position_features(position,m.input_width,nx,ny)||!ama10_step_features(&m,&st,position,logits,2,2.0f)){ok=0;goto done;}codes[p]=sample_code(logits,256,book.code_count,temp,&random_state);if(!ama10_step(&m,&st,256+codes[p]-1,logits,2,2.0f)){ok=0;goto done;}}
 }else{
  for(size_t p=0;p<ncodes;p++){size_t px=p%grid_w,py=p/grid_w;uint32_t yt=coord_token(1,normalized_coord(py,grid_h),book.code_count),xt=coord_token(0,normalized_coord(px,grid_w),book.code_count);if(!ama10_step(&m,&st,yt,logits,2,2.0f)||!ama10_step(&m,&st,xt,logits,2,2.0f)){ok=0;goto done;}codes[p]=sample_code(logits,256,book.code_count,temp,&random_state);if(!ama10_step(&m,&st,256+codes[p]-1,logits,2,2.0f)){ok=0;goto done;}}
 }
 ok=ama10_image_decode_codes_size(&book,codes,ncodes*book.levels,width,height,&im)&&ama10_image_save_ppm(&im,argv[3]);if(ok){print_code_metrics(codes,ncodes,book.levels,book.code_count,&im,grid_w,grid_h,book.stride_width,book.stride_height);printf("mean_image_code_model_entropy_nats=%.4f mean_image_code_model_top1_probability=%.4f predictions=%zu\n",image_prediction_count?image_entropy_sum/(double)image_prediction_count:0.0,image_prediction_count?image_top1_sum/(double)image_prediction_count:0.0,image_prediction_count);printf("generated=%zux%zu ppm visual_codes=%zu residual_levels=%u conditioning=%s patch=%ux%u stride=%ux%u temperature=%.2f seed=%llu checkpoint_update=%llu output=%s\n",width,height,ncodes*book.levels,book.levels,hierarchical?"hierarchical":"positioned",book.patch_width,book.patch_height,book.stride_width,book.stride_height,temp,(unsigned long long)random_seed,(unsigned long long)pr.completed_updates,argv[3]);}
done:if(!ok)fprintf(stderr,"image generation failed\n");ama10_image_free(&im);free(codes);free(layout_codes);free(context_codes);free(logits);free(position);free(ids);free(text);ama10_image_codebook_free(&book);ama10_state_free(&st);ama10_optimizer_free(&opt);ama10_model_free(&m);ama10_tokenizer_free(&tok);return ok?0:1;}
